import{_ as c,a as i}from"./peer-turn-a1dccb92.js";import{_ as l}from"./plugin-vue_export-helper-c27b6911.js";import{r as o,o as r,c as u,d as s,e as n,b as a,w as p,a as d,f as k}from"./app-901c4b09.js";const m={},g=s("code",null,"dsh-peer",-1),h=s("strong",null,"怎么在对方 agent 跑一轮的时候插话，甚至中止它",-1),v=s("p",null,[n('绕了一圈才明白：在 DSH 里，"发消息"其实有三种粒度——'),s("code",null,"prompt"),n("、"),s("code",null,"steer"),n("、"),s("code",null,"cancel"),n("。它们的差别不在网络层，而在 "),s("strong",null,"agent loop 的 turn/step 边界"),n("。这篇把语义、协议和一次真实的联调记录放在一起。")],-1),b=k(`<h2 id="_1-起点-peer-调用其实是一个-tool-call" tabindex="-1"><a class="header-anchor" href="#_1-起点-peer-调用其实是一个-tool-call" aria-hidden="true">#</a> 1. 起点：peer 调用其实是一个 tool call</h2><p>对模型来说，<code>peer_ask</code> 就是一个普通工具：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>assistant: tool/call peer_ask { peer: &quot;macmini&quot;, prompt: &quot;帮我跑个长任务&quot; }
tool:      peer_ask 结果 { text: &quot;...&quot;, status: &quot;completed&quot;, elapsedMs: 42000 }
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>对端是另一台机器上的完整 runtime，有它自己的模型、工具和会话；但在这边，它被包成了&quot;入参是 prompt、出参是最终文本&quot;的函数。</p><p>这个抽象有三个天然的短板：</p><ol><li><strong>没有流式</strong>：tool 结果一次性返回，看不到对方正在做什么（所以有了镜像会话）</li><li><strong>不能反问</strong>：对方不能在同一次调用里问回来</li><li><strong>不能抢占</strong>：调用期间无法干预对方</li></ol><p>前两个已经用镜像和 inbox 补过；这一次补第三个。</p><h2 id="_2-dsh-里一轮到底是怎么跑的" tabindex="-1"><a class="header-anchor" href="#_2-dsh-里一轮到底是怎么跑的" aria-hidden="true">#</a> 2. DSH 里一轮到底是怎么跑的</h2><p>先把运行时说清楚，否则 <code>steer</code> 和 <code>prompt</code> 的区别很容易被误解成&quot;发消息的时机不同&quot;。</p><p>DSH 的 agent loop 里，<strong>turn 由多个 step 组成</strong>，每个 step 是一次 LLM 请求 + 工具执行：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>turn/start
  ├─ step 1: step/start → LLM 请求 → tool/call → tool/result → step/end
  ├─ step 2: step/start → LLM 请求 → ...
  └─ turn/end
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>每一轮开始前，driver 会从 <strong>inbox</strong> 里 claim 消息，分成两个队列：</p><table><thead><tr><th>队列</th><th>谁写入</th><th>何时消费</th></tr></thead><tbody><tr><td><code>next-turn</code></td><td><code>prompt</code> / <code>followup</code></td><td>当前轮结束后，作为下一轮的第一条输入</td></tr><tr><td><code>next-step</code></td><td><code>steer</code> / <code>inject</code></td><td><strong>下一个 step 开始前</strong>，和当前轮的其他输入一起</td></tr></tbody></table><p>对应到 DSH 的 <code>Agent</code> 接口：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token function">followup</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">send</span><span class="token punctuation">(</span>message<span class="token punctuation">,</span> <span class="token string">&#39;next-turn&#39;</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">}</span>  <span class="token comment">// 排队下一轮</span>
<span class="token function">steer</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span>    <span class="token punctuation">{</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">send</span><span class="token punctuation">(</span>message<span class="token punctuation">,</span> <span class="token string">&#39;next-step&#39;</span><span class="token punctuation">,</span> <span class="token boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">}</span>  <span class="token comment">// 插到下一步</span>
<span class="token function">cancel</span><span class="token punctuation">(</span>cause<span class="token punctuation">)</span>     <span class="token punctuation">{</span> <span class="token comment">/* 中止当前 activity */</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>几个容易被忽略的细节：</p><ul><li><strong>steer 不打断当前 step</strong>：正在跑的工具会跑完，消息在下一个 step 才被模型看到</li><li><strong>steer 能让一轮&quot;续命&quot;</strong>：如果模型本来已经决定结束，但 <code>next-step</code> 里还有消息，loop 会再开一个 step 而不是 break</li><li><strong>cancel 会保留队列</strong>：<code>keepInbox: true</code> 时，已排队的 steer 不丢，留给下一轮</li><li><strong>inbox 是持久化的</strong>：它是 session projection，写在会话日志里，重启后还在</li></ul><p>所以三种粒度是：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>prompt  → 下一轮
steer   → 下一个 step（当前轮继续）
cancel  → 立即中止（当前轮结束）
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-协议设计" tabindex="-1"><a class="header-anchor" href="#_3-协议设计" aria-hidden="true">#</a> 3. 协议设计</h2><p>在 wire 上加了三个方法，由 link 侧的 <code>PeerHarnessServer</code> 处理：</p><table><thead><tr><th>方法</th><th>参数</th><th>返回</th></tr></thead><tbody><tr><td><code>session/steer</code></td><td><code>{ sessionId, contentBlocks }</code></td><td><code>{ accepted, messageId }</code></td></tr><tr><td><code>session/cancel</code></td><td><code>{ sessionId, reason? }</code></td><td><code>{ cancelled, status }</code></td></tr><tr><td><code>session/state</code></td><td><code>{ sessionId }</code></td><td><code>{ status, seq }</code></td></tr></tbody></table><p>link 侧的实现很短，关键只有一句：<strong>只允许操作这个 server 自己创建过的 session</strong>。</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">async</span> <span class="token function">handleRequest</span><span class="token punctuation">(</span><span class="token parameter">method<span class="token punctuation">,</span> params</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;session/steer&#39;</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#steer</span><span class="token punctuation">(</span>params<span class="token punctuation">)</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;session/cancel&#39;</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#cancel</span><span class="token punctuation">(</span>params<span class="token punctuation">)</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;session/state&#39;</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#state</span><span class="token punctuation">(</span>params<span class="token punctuation">)</span>
  <span class="token keyword">return</span> <span class="token keyword">super</span><span class="token punctuation">.</span><span class="token function">handleRequest</span><span class="token punctuation">(</span>method<span class="token punctuation">,</span> params<span class="token punctuation">)</span>
<span class="token punctuation">}</span>

<span class="token function">#steer</span><span class="token punctuation">(</span><span class="token parameter">params</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> record <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#record</span><span class="token punctuation">(</span>params<span class="token punctuation">)</span>          <span class="token comment">// this.sessions.get(sessionId)，没有就抛错</span>
  <span class="token keyword">const</span> message <span class="token operator">=</span> <span class="token function">createUserMessage</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">content</span><span class="token operator">:</span> params<span class="token punctuation">.</span>contentBlocks<span class="token punctuation">,</span> <span class="token literal-property property">source</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">kind</span><span class="token operator">:</span> <span class="token string">&#39;user&#39;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">)</span>
  record<span class="token punctuation">.</span>handle<span class="token punctuation">.</span>agent<span class="token punctuation">.</span><span class="token function">steer</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span>           <span class="token comment">// 进 next-step</span>
  <span class="token keyword">return</span> <span class="token punctuation">{</span> <span class="token literal-property property">accepted</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token literal-property property">messageId</span><span class="token operator">:</span> message<span class="token punctuation">.</span>id <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>hub 侧做路由和限流：</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">async</span> <span class="token function">steer</span><span class="token punctuation">(</span><span class="token parameter">request</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> link <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">require</span><span class="token punctuation">(</span>request<span class="token punctuation">.</span>peer<span class="token punctuation">)</span>
  <span class="token keyword">const</span> sessionId <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#sessionFor</span><span class="token punctuation">(</span>link<span class="token punctuation">,</span> request<span class="token punctuation">.</span>session<span class="token punctuation">,</span> <span class="token boolean">false</span><span class="token punctuation">)</span>
  <span class="token keyword">const</span> state <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#state</span><span class="token punctuation">(</span>link<span class="token punctuation">,</span> sessionId<span class="token punctuation">)</span>

  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#supportsSteer</span><span class="token punctuation">(</span>link<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>             <span class="token comment">// 版本门：&lt; 0.3.0 降级</span>
    <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#prompt</span><span class="token punctuation">(</span>link<span class="token punctuation">,</span> sessionId<span class="token punctuation">,</span> request<span class="token punctuation">.</span>text<span class="token punctuation">,</span> <span class="token string">&#39;prompt&#39;</span><span class="token punctuation">)</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>state<span class="token punctuation">.</span>status <span class="token operator">===</span> <span class="token string">&#39;running&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>             <span class="token comment">// 跑着 → 插话</span>
    <span class="token keyword">const</span> result <span class="token operator">=</span> <span class="token keyword">await</span> link<span class="token punctuation">.</span>conn<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;session/steer&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> sessionId<span class="token punctuation">,</span> contentBlocks <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token keyword">return</span> <span class="token punctuation">{</span> <span class="token literal-property property">mode</span><span class="token operator">:</span> <span class="token string">&#39;steer&#39;</span><span class="token punctuation">,</span> <span class="token literal-property property">accepted</span><span class="token operator">:</span> result<span class="token punctuation">.</span>accepted<span class="token punctuation">,</span> <span class="token literal-property property">messageId</span><span class="token operator">:</span> result<span class="token punctuation">.</span>messageId <span class="token punctuation">}</span>
  <span class="token punctuation">}</span>
  <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">#prompt</span><span class="token punctuation">(</span>link<span class="token punctuation">,</span> sessionId<span class="token punctuation">,</span> request<span class="token punctuation">.</span>text<span class="token punctuation">,</span> <span class="token string">&#39;prompt&#39;</span><span class="token punctuation">)</span>  <span class="token comment">// 空闲 → 起新轮</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>另外两条约束：</p><ul><li><strong>版本门</strong>：link 版本低于 0.3.0 时，steer 降级为 prompt，cancel 直接报错——避免对端收到未知方法后静默失败</li><li><strong>限流</strong>：每个 peer 每分钟 20 次 steer/cancel（<code>steerPerMinute</code> 可配），防止刷屏</li></ul><h2 id="_4-反问为什么总是晚一轮" tabindex="-1"><a class="header-anchor" href="#_4-反问为什么总是晚一轮" aria-hidden="true">#</a> 4. 反问为什么总是晚一轮</h2><p>这是联调时最容易被问住的地方：link 问 hub 一个问题，hub 也回答了，但回答要等 link 当前轮结束才看到。</p><p>原因在 hub 回答的那一步：它走的是 <code>session/prompt</code>，而 SDK server 收到 prompt 后调用的是：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code>rec<span class="token punctuation">.</span>handle<span class="token punctuation">.</span>agent<span class="token punctuation">.</span><span class="token function">followup</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span>   <span class="token comment">// 注意是 followup，不是 steer</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>followup</code> 进的是 <code>next-turn</code>。所以：</p><figure><img src="`+c+'" alt="反问流程：回答为什么晚一轮才到" tabindex="0" loading="lazy"><figcaption>反问流程：回答为什么晚一轮才到</figcaption></figure><p>要点：</p><ul><li><code>peer_ask</code> / <code>peer_send</code> 只是 hub <strong>把回答文本送出去</strong>的两种方式，不是&quot;查询处理进度&quot;</li><li>回答变成 link 的一条 user 消息，排进它的下一轮</li><li>link 拿到的是&quot;送达回执&quot;，不是回答本身</li></ul><p>要让它&quot;问完立刻拿到答复&quot;，有两条路：请求-响应式（hub 挂起 RPC 直到本轮结束再返回）或者收件箱式（link 端 <code>peer_wait</code>）。两者都要额外协议，这篇先不展开。</p><h2 id="_5-三种粒度在-turn-里的位置" tabindex="-1"><a class="header-anchor" href="#_5-三种粒度在-turn-里的位置" aria-hidden="true">#</a> 5. 三种粒度在 turn 里的位置</h2><figure><img src="'+i+`" alt="Peer turn / steer / cancel 交互" tabindex="0" loading="lazy"><figcaption>Peer turn / steer / cancel 交互</figcaption></figure><h2 id="_6-联调-一次真实的-steer-cancel-测试" tabindex="-1"><a class="header-anchor" href="#_6-联调-一次真实的-steer-cancel-测试" aria-hidden="true">#</a> 6. 联调：一次真实的 steer / cancel 测试</h2><p>macmini 升到 0.3.0 之后，做了一次端到端验证：</p><p><strong>第一步：发一个不等待的长任务</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>peer_send(peer=&quot;macmini&quot;, prompt=&quot;for i in $(seq 1 90); do echo tick $i; sleep 1; done; echo DONE_LONG_TASK&quot;)
→ Queued on [macmini] session peer-macmini-chat (message ffbc6bf8-...)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>第二步：等会话进入 running</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>sleep 6
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>第三步：插话</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>peer_steer(peer=&quot;macmini&quot;, text=&quot;联调插话：如果你在下一步看到这句，请在报告里注明 STEER_OK&quot;)
→ Steered into macmini; delivered at its next step.   (mode: &#39;steer&#39;)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>第四步：中止</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>peer_cancel(peer=&quot;macmini&quot;, reason=&quot;steer/cancel 联调&quot;)
→ Cancelled the current turn on macmini.              (cancelled: true)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>两个返回值都符合预期，而且 cancel 之后 link 仍然保持连接：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>macmini (darwin/arm64, host ?, dsh 0.3.0) cwd=/Users/patrick
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="两个语义细节" tabindex="-1"><a class="header-anchor" href="#两个语义细节" aria-hidden="true">#</a> 两个语义细节</h3><ol><li><strong>steer 的&quot;已投递&quot;是入队</strong>：90 秒的命令还在跑时，消息只是进了 <code>next-step</code>；模型要等这个 step 结束才会看到。我们紧接着 cancel 了，所以它按 <code>keepInbox: true</code> 留在队列里，会在下一轮被消费——不会丢。</li><li><strong>cancel 是中止 turn，不是杀进程</strong>：运行中的 shell 命令可能继续跑完，但 agent 不再推进本轮。</li></ol><h2 id="_7-联调顺手抓到的-bug-漏了一个-import" tabindex="-1"><a class="header-anchor" href="#_7-联调顺手抓到的-bug-漏了一个-import" aria-hidden="true">#</a> 7. 联调顺手抓到的 bug：漏了一个 import</h2><p>联调过程中 macmini 反复出现&quot;握手失败、静默重连&quot;。看起来像网络问题，实际是一行 import：</p><div class="language-diff line-numbers-mode" data-ext="diff"><pre class="language-diff"><code><span class="token deleted-sign deleted"><span class="token prefix deleted">-</span><span class="token line"> import { PeerConnection, describeError, localIdentity } from &#39;./protocol.js&#39;
</span></span><span class="token inserted-sign inserted"><span class="token prefix inserted">+</span><span class="token line"> import { PeerConnection, PEER_VERSION, describeError, localIdentity } from &#39;./protocol.js&#39;
</span></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>link.js</code> 在 <code>status()</code>、<code>peer/hello</code> 和重连状态里用了 <code>PEER_VERSION</code>，但只有 <code>hub.js</code> 引入了它。每次拨号都会在握手 try/catch 里抛 <code>ReferenceError</code>，被记成 handshake failed 后按退避重连，日志里看不到真正的异常。</p><p>修复提交：<code>38f6c10</code>（<code>SparksDing/dsh-peer</code>，<code>feat/session-mirror</code>）。</p><p>这个 bug 的教训比修复本身重要：<strong>跨机器链路的错误如果被 catch 吞掉，现象会伪装成网络问题</strong>。握手阶段至少要保留原始异常。</p><h2 id="_8-还没做的" tabindex="-1"><a class="header-anchor" href="#_8-还没做的" aria-hidden="true">#</a> 8. 还没做的</h2><ul><li><strong>代码级权限约束</strong>：peer 来源的消息目前只是普通 user 消息，被唤醒的 turn 用的是用户会话的权限。下一步要让 peer 来源的 turn 强制使用受限 preset，特权操作必须真人批准——安全不能只靠 prompt 提示词</li><li><strong>link 端 inbox / wait</strong>：现在 link 只能&quot;发&quot;，不能在同一轮里等 hub 的回答</li><li><strong>来源落盘</strong>：wire 上带 <code>origin</code>，把&quot;这条消息来自哪个 peer&quot;写进消息 source，而不是靠文本前缀</li></ul><h2 id="_9-小结" tabindex="-1"><a class="header-anchor" href="#_9-小结" aria-hidden="true">#</a> 9. 小结</h2><ul><li><code>prompt</code> / <code>steer</code> / <code>cancel</code> 的区别在 <strong>turn/step 边界</strong>，不在网络</li><li>steer 是&quot;下一步插话&quot;，不打断当前 step；cancel 是&quot;中止 activity&quot;，不是杀进程</li><li>协议上要加<strong>版本门</strong>和<strong>限流</strong>，否则旧版本会静默失败</li><li>跨机器调试，先怀疑&quot;异常被吞了&quot;，再怀疑网络</li></ul><p>代码：</p>`,64),f={href:"https://github.com/SparksDing/dsh-peer",target:"_blank",rel:"noopener noreferrer"},x=s("code",null,"feat/session-mirror",-1),_={href:"https://github.com/SparksDing/deepseek-harness",target:"_blank",rel:"noopener noreferrer"},y=s("code",null,"feat/peer-session-mirror",-1);function q(w,I){const e=o("RouterLink"),t=o("ExternalLinkIcon");return r(),u("div",null,[s("p",null,[n("上一篇 "),a(e,{to:"/architecture/dsh-peer.html"},{default:p(()=>[n("让两个 DeepSeek Harness 跨机器对话")]),_:1}),n(" 写了 "),g,n(" 的连接方向和活动看板。这一篇接着写一个更细的问题："),h,n("。")]),v,s("blockquote",null,[s("p",null,[n("English version: "),a(e,{to:"/en/architecture/dsh-peer-steer.html"},{default:p(()=>[n("Adding steer and cancel to a two-agent channel")]),_:1})])]),d(" more "),b,s("ul",null,[s("li",null,[s("a",f,[n("SparksDing/dsh-peer"),a(t)]),n("（"),x,n("）")]),s("li",null,[n("fork: "),s("a",_,[n("SparksDing/deepseek-harness"),a(t)]),n("（"),y,n("）")])])])}const D=l(m,[["render",q],["__file","dsh-peer-steer.html.vue"]]);export{D as default};
